import { ResearchAgentAnalysis, DeepDiveResponse } from '../types/research';

export function generateMarkdownReport(analysis: ResearchAgentAnalysis): string {
  const { topic, timestamp, lens, thinkingSteps, step1SubQuestions, step2Papers, step2KeyAuthors, step3Findings, step4Gaps } = analysis;

  return `# Literature Analysis & Research Agent Report: ${topic}
*Generated by ScholarPulse Academic Agent on ${new Date(timestamp).toLocaleDateString()} | Lens: ${lens}*

---

## 1. Agent Reasoning & Step-by-Step Thinking
- **Phase 1 (Decomposition):** ${thinkingSteps.step1Reasoning}
- **Phase 2 (Literature Mining):** ${thinkingSteps.step2Reasoning}
- **Phase 3 (Synthesis & Tradeoffs):** ${thinkingSteps.step3Reasoning}
- **Phase 4 (Gap Discovery):** ${thinkingSteps.step4Reasoning}

---

## 2. Step 1: Sub-Questions Breakdown
${step1SubQuestions.map((sq, i) => `### 1.${i + 1} [${sq.category.toUpperCase()}] ${sq.question}
- **Priority:** ${sq.priority}
- **Scientific Rationale:** ${sq.rationale}
- **Key Facets:** ${sq.keyFacets.join(', ')}
`).join('\n')}

---

## 3. Step 2: Key Papers & Seminal Authors

### Landmark & Foundational Papers
${step2Papers.map((p, i) => `#### [${i + 1}] ${p.title} (${p.year})
- **Authors:** ${p.authors.join(', ')}
- **Venue:** ${p.venue} | **Type:** ${p.paperType}
- **Abstract Summary:** ${p.abstractSummary}
- **Key Innovation:** ${p.keyInnovation}
${p.doi ? `- **DOI:** https://doi.org/${p.doi}` : ''}
${p.arxivId ? `- **arXiv:** https://arxiv.org/abs/${p.arxivId}` : ''}
${p.citationsEstimate ? `- **Estimated Citations:** ${p.citationsEstimate}` : ''}
`).join('\n')}

### Seminal Authors & Principal Investigators
${step2KeyAuthors.map(a => `#### ${a.name} (${a.affiliation})
- **Landmark Contribution:** ${a.landmarkContribution}
- **Notable Works:** ${a.notablePapers.join('; ')}
`).join('\n')}

---

## 4. Step 3: Synthesis of Findings & Tradeoffs

### Executive Synthesis
${step3Findings.executiveSynthesis}

${step3Findings.theoreticalFormulation ? `### Theoretical Formulation\n\`\`\`text\n${step3Findings.theoreticalFormulation}\n\`\`\`\n` : ''}

### Thematic Findings
${step3Findings.thematicFindings.map(f => `#### ${f.topic}
- **Consensus:** ${f.consensus}
- **Key Mechanisms:** ${f.keyMechanisms}
- **Empirical Evidence:** ${f.empiricalEvidence}
`).join('\n')}

### Comparative Trade-offs Matrix
| Method | Strengths | Limitations | Tradeoffs | Ideal Use Case |
|---|---|---|---|---|
${step3Findings.tradeoffsMatrix.map(t => `| **${t.methodName}** | ${t.strengths} | ${t.limitations} | ${t.tradeoffs} | ${t.idealUseCase} |`).join('\n')}

---

## 5. Step 4: Research Gaps & Open Challenges
${step4Gaps.map((g, i) => `### Gap ${i + 1}: ${g.title}
- **Type:** ${g.gapType} | **Severity:** ${g.severity}
- **Description:** ${g.description}
- **Why Existing Methods Fail:** ${g.whyExistingMethodsFail}
- **Actionable Research Angle:** ${g.actionableResearchAngle}
- **Recommended Hypothesis:** *${g.recommendedHypothesis}*
`).join('\n')}
`;
}

export function generateBibTeX(analysis: ResearchAgentAnalysis): string {
  return analysis.step2Papers.map(p => {
    if (p.bibtex) return p.bibtex.trim();
    const citeKey = `${(p.authors[0] || 'author').split(' ').pop()?.toLowerCase() || 'paper'}${p.year}${p.title.split(' ')[0].toLowerCase()}`;
    return `@article{${citeKey},
  title = {${p.title}},
  author = {${p.authors.join(' and ')}},
  journal = {${p.venue}},
  year = {${p.year}},
  url = {${p.doi ? `https://doi.org/${p.doi}` : (p.arxivId ? `https://arxiv.org/abs/${p.arxivId}` : '')}}
}`;
  }).join('\n\n');
}

export function downloadTextFile(filename: string, content: string, mimeType = 'text/plain') {
  const blob = new Blob([content], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}
